insert into public.iskra_shared_kb (topic, topic_norm, body, tags) values
  ('Как выбрать смартфон', public.iskra_kb_norm('Как выбрать смартфон'), 'Определи три вещи: бюджет, размер экрана и сколько лет планируешь пользоваться. Смотри процессор и объём памяти (минимум 128 ГБ), ёмкость батареи от 4500 мАч, поддерживается ли 5G и как долго обещают обновления системы — у разных производителей это от 2 до 7 лет. Камера важна меньше, чем кажется: разницу видно только на большом экране. Перед покупкой проверь наличие сервиса в твоём городе.', 'техника, смартфон, покупка'),
  ('Телефон быстро разряжается', public.iskra_kb_norm('Телефон быстро разряжается'), 'Сначала проверь, что ест батарею: в настройках есть раздел «Аккумулятор» с расходом по приложениям. Чаще всего виноваты экран (автояркость и тёмная тема помогают), фоновая синхронизация, геолокация и приложения, которые ты не открывала неделю. Отключи автозапуск лишнего, снизь частоту обновления экрана. Если батарея греется и садится на глазах даже в простое — она изношена, замена дешевле нового телефона.', 'техника, телефон, батарея'),
  ('Как освободить память на телефоне', public.iskra_kb_norm('Как освободить память на телефоне'), 'Начни с фотографий и видео — они занимают больше всего. Включи автозагрузку в облако и удаляй копии с телефона. Дальше мессенджеры: кэш и старые видео в общих чатах весят гигабайты, чистить можно из настроек каждого приложения. Удали игры, в которые не играешь месяц, и скачанные фильмы. Приложения не столько занимают место, сколько их данные. Освобождать по 2–3 ГБ каждую неделю проще, чем один раз всё под ноль.', 'техника, память, телефон'),
  ('Резервная копия фото', public.iskra_kb_norm('Резервная копия фото'), 'Потеря телефона не должна означать потерю фотографий. Включи автозагрузку в облачный сервис (у большинства бесплатно 5–15 ГБ) и в настройках поставь «загружать только по Wi-Fi». Раз в месяц скачивай архив на компьютер или внешний диск: облако — не единственное место, аккаунт могут заблокировать. Проверь восстановление на другом устройстве — копия, которую ни разу не открывали, копией не считается.', 'техника, фото, резервная копия'),
  ('Мошенники по телефону', public.iskra_kb_norm('Мошенники по телефону'), 'Настоящие банк, полиция и госуслуги никогда не просят назвать код из SMS, перевести деньги «на безопасный счёт» и не торопят. Признаки обмана: незнакомый номер, давление срочностью, просьба установить программу удалённого доступа, предложение «помочь оформить» кредит. Правильное действие одно — положить трубку и самому позвонить в банк по номеру с обратной стороны карты. Если уже перевёл деньги — звони в банк и в полицию сразу, чем быстрее, тем больше шансов вернуть.', 'безопасность, мошенники, телефон'),
  ('Как хранить пароли', public.iskra_kb_norm('Как хранить пароли'), 'Один пароль на все сайты — самая частая причина взломов: утечка на форуме открывает почту и банк. Пароли должны быть разными, длинными (12+ символов) и придуманными не из слов. Запоминать их не нужно — держи менеджер паролей (встроенный в браузер или отдельный), он подставит нужный пароль сам. Главный пароль от менеджера и от почты запомни и никому не диктуй: почта — ключ ко всему остальному.', 'безопасность, пароли, аккаунты'),
  ('Двухфакторная защита', public.iskra_kb_norm('Двухфакторная защита'), 'Два фактора — это пароль плюс код из приложения или SMS. Включи её на почте, в соцсетях, в банке и на госуслугах: даже украденный пароль без второго кода бесполезен. Лучше приложение-аутентификатор, чем SMS: SIM-карту можно восстановить обманом. Сохрани резервные коды восстановления на бумаге или в менеджере паролей — иначе при потере телефона доступ не вернуть.', 'безопасность, двухфакторная, защита'),
  ('Что такое фишинг', public.iskra_kb_norm('Что такое фишинг'), 'Фишинг — поддельная страница или письмо, которое выманивает пароль. Признаки: адрес сайта с опечаткой (sber-online вместо sberbank), письмо с «срочно подтвердите аккаунт», ссылка в сообщении вместо входа через приложение, странные вложения. Правило простое: не переходи по ссылкам из писем о деньгах и не вводи пароль, если сам не открывал сайт. Проверяй адрес в строке браузера до ввода данных, а не после.', 'безопасность, фишинг, интернет'),
  ('Покупка в интернете без риска', public.iskra_kb_norm('Покупка в интернете без риска'), 'Покупай на крупных площадках с защитой покупателя и оплатой при получении, если есть сомнения. Смотри не только рейтинг товара, но и оценки магазина, срок работы, отзывы с фото. Не переводи деньги на карту частному лицу за товар, который не видел. Сохраняй переписку и чек: при споре это доказательство. Слишком низкая цена — почти всегда подвох или подделка.', 'интернет, покупки, безопасность'),
  ('Возврат товара в магазин', public.iskra_kb_norm('Возврат товара в магазин'), 'По закону о защите прав потребителей непродовольственный товар можно вернуть в течение 14 дней, если он не был в употреблении, сохранены упаковка, ярлыки и чек. Есть список товаров, которые вернуть нельзя: лекарства, бельё, косметика, животные, мебель на заказ. Технику с браком возвращают в течение гарантии, гарантия обычно год и больше. Пиши заявление в двух экземплярах и оставляй себе подпись продавца — это ускоряет возврат денег.', 'покупки, возврат, права'),
  ('Меню на неделю', public.iskra_kb_norm('Меню на неделю'), 'Сэкономить время и деньги помогает простая схема: выбери 4–5 блюд на неделю, из них два — на два дня. Составь список продуктов по рецептам и иди в магазин один раз. Держи дома «базу»: крупы, макароны, яйца, замороженные овощи, консервы. Готовь основу заранее — варёная крупа и мясо доживают до средины недели. Планируй один «ленивый» день на пельмени или доставку, иначе план сорвётся.', 'дом, еда, планирование'),
  ('Как хранить продукты', public.iskra_kb_norm('Как хранить продукты'), 'В холодильнике холоднее всего внизу и у задней стенки — туда мясо и рыба, выше — готовое, в дверце — соусы и напитки, не молоко. Фрукты и овощи лучше в ящиках, но не вместе: яблоки выделяют газ, от которого портятся другие овощи. Хлеб и картошку — в тёмном сухом месте, не в холодильнике. Готовое храни не больше 2–3 дней, замороженное — по сроку на упаковке, и подписывай дату, когда замораживаешь.', 'дом, продукты, холодильник'),
  ('Быстрая уборка квартиры', public.iskra_kb_norm('Быстрая уборка квартиры'), 'Работает система «сверху вниз, от чистого к грязному»: сначала пыль с полок и подоконников, потом пол, иначе пыль снова осядет. Начни с 15 минут в одной комнате — таймер помогает не растягивать. Держи в каждой комнате по тряпке и мешку для мусора, чтобы не бегать. Раз в неделю — полы и санузел, раз в месяц — окна и шкафы. Беспорядок убирается быстрее, если у каждой вещи есть место.', 'дом, уборка, порядок'),
  ('Как стирать разные ткани', public.iskra_kb_norm('Как стирать разные ткани'), 'Посмотри ярлык на вещи — там всё написано значками и это важнее любого совета. Шерсть и шёлк — только деликатный режим в мешке, без отжима на высоких оборотах и без сушилки. Хлопок и лён держат 40–60 градусов, синтетика — 30–40. Джинсы выворачивай и стирай редко, они теряют цвет. Сортировать стоит не только по цвету, но и по типу ткани, а молнии и крючки застёгивать, чтобы не порвали остальное.', 'дом, стирка, одежда'),
  ('Как убрать пятна', public.iskra_kb_norm('Как убрать пятна'), 'Пятно надо промокнуть, а не тереть — трение вбивает его в ткань. Свежее пятно от кофе или чая заливают холодной водой, жир посыпают солью или тальком и ждут, потом стирают с мылом. Кровь — только холодная вода, горячая сворачивает белок и закрепляет пятно. Не гладь вещь, пока не уверен, что пятно ушло: утюг фиксирует его навсегда. На деликатных тканях сначала проверь средство на незаметном участке.', 'дом, пятна, одежда'),
  ('Комнатные растения', public.iskra_kb_norm('Комнатные растения'), 'Большинство домашних растений гибнет не от нехватки ухода, а от перелива: корни задыхаются и гниют. Поливай, когда верхний слой земли просох на палец, и всегда проверяй дренаж в горшке. Ставь туда, где есть рассеянный свет, а не прямые лучи весь день. Протирай листья от пыли раз в месяц. Пересаживают, когда корни заполнили горшок, обычно раз в 1–2 года, весной.', 'дом, растения, цветы'),
  ('Как выбрать домашнее животное', public.iskra_kb_norm('Как выбрать домашнее животное'), 'Считай не только желание, но и время и деньги: корм, ветеринар, прививки, иногда передержка в отпуске. Собака требует прогулок каждый день минимум час и компании, кошка переносит одиночество легче, но живёт 15–20 лет. Для маленькой квартиры плохо подходят крупные активные породы. Бери животное из приюта или у заводчика с документами, а не «по объявлению с рук». Заведи привычку проверять у питомца уши, зубы и шерсть — так болезни ловятся раньше.', 'животные, питомцы, выбор'),
  ('Собака тянет поводок', public.iskra_kb_norm('Собака тянет поводок'), 'Тянуть — не вредность, а привычка: собака быстро поняла, что натянутый поводок приближает к цели. Остановись, как только поводок натянулся, дождись, пока ослабнет, и только потом иди. Правило «натянуто — стоим, свободно — идём» работает за пару недель. Гуляй на коротком поводке в начале прогулки, поощряй лакомством, когда собака идёт рядом. Рывки и строгий ошейник — путь к травмам и недоверию.', 'животные, собака, воспитание'),
  ('Как научить ребёнка читать', public.iskra_kb_norm('Как научить ребёнка читать'), 'Начинать лучше с того, что ребёнку нравится: книги с картинками, короткие истории на 5 минут. Не заставляй дочитывать то, что не идёт — интерес важнее программы. Читайте вслух по очереди, обсуждайте прочитанное, спрашивайте «а как бы ты поступил». Обучение буквам идёт легче через игру: кубики, вывески, подписи в альбоме. Хвали за попытку, а не за правильность, и никогда не сравнивай с другими детьми.', 'дети, чтение, учёба'),
  ('Как готовиться к экзамену', public.iskra_kb_norm('Как готовиться к экзамену'), 'Учить надо не зубрежкой, а вопросами: закрой конспект и попробуй объяснить тему вслух — так находится пробел. Работает распределение: 5 подходов по 30 минут за неделю лучше, чем 3 часа подряд в ночь перед экзаменом. Пиши короткие карточки с вопросом и ответом, повторяй их через день, три и неделю. Спи не меньше 7 часов: без сна выученное не переносится в долгую память. В день экзамена не учи новое — только просмотри карточки.', 'учёба, экзамен, память'),
  ('Как перестать откладывать', public.iskra_kb_norm('Как перестать откладывать'), 'Прокрастинация — не лень, а способ избежать неприятного чувства перед задачей. Поэтому работает не сила воли, а уменьшение задачи: договорись с собой сделать 5 минут или одну строку. Начни с самой скучной части, пока голова свежая. Убери с глаз телефон на эти 5 минут. Записывай задачи конкретно: не «учеб», а «прочитать 10 страниц до обеда». Срыв не отменяет план — просто начни снова с пяти минут.', 'психология, привычки, дела'),
  ('Как говорить нет', public.iskra_kb_norm('Как говорить нет'), 'Отказ не обязан включать оправдание. Работает короткая формула: «сейчас не могу» или «мне это не подходит», без объяснений и извинений. Если давят, повторяй ту же фразу другими словами — это называется заезженной пластинкой. Предлагай альтернативу, только если правда хочешь помочь: «сегодня нет, в субботу могу». Чувство вины после отказа нормально первые минуты, оно проходит, а сделанное через силу остаётся надолго.', 'психология, отношения, границы'),
  ('Как правильно извиняться', public.iskra_kb_norm('Как правильно извиняться'), 'Настоящее извинение состоит из трёх частей: что именно я сделал, как это повлияло на тебя, что я сделаю иначе. Без «но» и без «если ты обиделся» — это не извинение, а защита. Не проси прощения сразу, дай человеку сказать, что он чувствует. Извинение не отменяет последствий: если испортил вещь — почини, если подвёл с делом — сделай заново. Хорошее извинение меняет поведение, а не только слова.', 'психология, отношения, общение'),
  ('Как высыпаться', public.iskra_kb_norm('Как высыпаться'), 'Взрослому нужно 7–9 часов, и это не роскошь: недосып бьёт по памяти, иммунитету и настроению сильнее, чем кажется. Главное — постоянное время подъёма, даже в выходные: организм живёт по ритму, а не по будильнику. За час до сна убери яркий экран и тяжёлую еду, комнату проветри и сделай прохладной. Кофеин работает 6–8 часов, поэтому кофе после обеда ворует сон. Если не спится 20 минут — встань, почитай при тусклом свете, вернись в постель.', 'здоровье, сон, отдых'),
  ('Как пить меньше кофе', public.iskra_kb_norm('Как пить меньше кофе'), 'Резко бросать не надо: организм ответит головной болью и разбитостью 2–3 дня. Уменьшай постепенно — на полчашки в неделю, и заменяй часть дозы на чай или воду. Не пей кофе после 14–15 часов, чтобы к ночи не оставался кофеин. Если хочется кофе от усталости, сначала попробуй выпить воды и пройтись 10 минут — часто помогает больше. Две-три чашки в день для здорового взрослого считаются безопасными.', 'здоровье, кофе, привычки'),
  ('Как выбрать очки для компьютера', public.iskra_kb_norm('Как выбрать очки для компьютера'), 'Очки с «антиблакировкой» не лечат, но снижают усталость и блики от экрана. Важнее правильная посадка: оправа не давит на виски, зрачок напротив центра линзы, отражение экрана не видно на стекле. Если работаешь за компьютером больше 4 часов, при проверке зрения попроси выписать очки для «средней» дистанции (50–70 см), а не только для чтения. Не покупай готовые очки с полки при разной силе глаз — нужен рецепт.', 'здоровье, зрение, очки'),
  ('Как выбрать матрас', public.iskra_kb_norm('Как выбрать матрас'), 'Жёсткость подбирают по весу и привычке: тяжелее 90 кг и сон на животе — жёстче, до 60 кг и сон на боку — мягче. Пружины работают только в блоке с независимым пружинным механизмом, «вата» без пружин дёшево, но служит 3–5 лет. Пробуй лежать на матрасе 10–15 минут в своей позе прямо в магазине. Менять матрас стоит раз в 7–10 лет, и раньше, если появились впадины или по утрам болит спина.', 'дом, сон, покупка'),
  ('Как экономить электричество', public.iskra_kb_norm('Как экономить электричество'), 'Самые большие расходы — нагрев: обогреватель, бойлер, чайник, стиральная машина на высокой температуре. Каждый градус сверх 20–21 в комнате добавляет около 5% к счёту. Стирай на 30–40 градусах — для повседневной одежды этого достаточно. Выключай из розетки редко используемое: зарядки и телевизор в режиме ожидания тоже потребляют. Светодиодные лампы окупаются за год, если они горят каждый вечер.', 'дом, экономия, электричество'),
  ('Как выбрать ноутбук', public.iskra_kb_norm('Как выбрать ноутбук'), 'Смотри на три вещи: процессор (i5/Ryzen 5 и выше для работы), память (минимум 16 ГБ, чтобы браузер не тормозил) и накопитель SSD от 512 ГБ. Матрица важнее корпуса — IPS-экран не выцветает под углом. Вес и заряд важны, если носишь с собой: до 1,5 кг и 8 часов работы нормальный ориентир. Для учёбы и офиса хватит средней модели, для монтажа и 3D нужна видеокарта и больше памяти. Не покупай на «слабом» железе в расчёте на будущее — оно стареет быстрее.', 'техника, ноутбук, покупка')
